"use client";

import type { Transition } from "motion/react";
import {
  createContext,
  type ReactNode,
  type RefObject,
  useContext,
  useMemo,
} from "react";

// CSS variable references for ring chart theming
// Adapted: --border is a bare HSL triplet in the APP SYSTEM theme — wrap for paint use
